#include <bits/stdc++.h>

using namespace std;

using lli = long long;

const int MAX_NODES = 5007;

const lli INF = 1000000000LL;
const lli MOD = 1000000007LL;

struct Edge {
    int src, dst;
    lli capacity, weight, flow;
    Edge(int s, int d, lli cap, lli w) : src(s), dst(d), capacity(cap), weight(w), flow(0) {}
};

vector<Edge> edge_list;
lli dist[MAX_NODES], pot[MAX_NODES];
vector<int> adj[MAX_NODES];
int prev_edge[MAX_NODES];

void add_edge(int u, int v, lli cap, lli wgt) {
    adj[u].emplace_back(edge_list.size());
    edge_list.emplace_back(u, v, cap, wgt);
    adj[v].emplace_back(edge_list.size());
    edge_list.emplace_back(v, u, 0, -wgt);
}

void bellman_ford(int source, int nodes) {
    fill(pot, pot + MAX_NODES, INF);
    pot[source] = 0;
    for (int iter = 0; iter < nodes; ++iter) {
        for (size_t idx = 0; idx < edge_list.size(); ++idx) {
            auto& e = edge_list[idx];
            if (e.capacity == e.flow) continue;
            if (pot[e.src] == INF) continue;
            pot[e.dst] = min(pot[e.dst], pot[e.src] + e.weight);
        }
    }
}

void dijkstra(int source) {
    fill(dist, dist + MAX_NODES, INF);
    dist[source] = 0;
    set<pair<lli, int>> pq;
    pq.emplace(0, source);
    while (!pq.empty()) {
        auto [d_val, v] = *pq.begin();
        pq.erase(pq.begin());
        for (int eid : adj[v]) {
            auto& e = edge_list[eid];
            if (e.capacity == e.flow) continue;
            int w = e.dst;
            lli reduced_cost = e.weight + pot[v] - pot[w];
            if (dist[v] + reduced_cost < dist[w]) {
                pq.erase({dist[w], w});
                dist[w] = dist[v] + reduced_cost;
                prev_edge[w] = eid;
                pq.emplace(dist[w], w);
            }
        }
    }
}

pair<lli, lli> min_cost_max_flow(int src, int dst) {
    bellman_ford(src, 50);
    dijkstra(src);
    lli total_flow = 0, total_cost = 0;
    while (dist[dst] != INF) {
        lli bottleneck = INF;
        lli sum_cost = 0;
        for (int cur = dst; cur != src; ) {
            int eid = prev_edge[cur];
            bottleneck = min(bottleneck, edge_list[eid].capacity - edge_list[eid].flow);
            sum_cost += edge_list[eid].weight;
            cur = edge_list[eid].src;
        }
        total_flow += bottleneck;
        total_cost += bottleneck * sum_cost;
        for (int cur = dst; cur != src; ) {
            int eid = prev_edge[cur];
            edge_list[eid].flow += bottleneck;
            edge_list[eid ^ 1].flow -= bottleneck;
            cur = edge_list[eid].src;
        }
        dijkstra(src);
        for (int i = 0; i < MAX_NODES; ++i) pot[i] = dist[i];
    }
    return {total_cost, total_flow};
}

void process() {
    int n, m, k, c_val, d_val;
    cin >> n >> m >> k >> c_val >> d_val;
    vector<int> counts(n, 0);
    for (int i = 0; i < k; ++i) {
        int ai;
        cin >> ai;
        counts[--ai]++;
    }
    for (int i = 0; i < n; ++i) {
        add_edge(5000, i, counts[i], 0);
    }
    for (int it = 0; it < m; ++it) {
        int u, v;
        cin >> u >> v;
        --u; --v;
        for (int i = 0; i < 99; ++i) {
            lli edge_cost = d_val;
            for (int j = 0; j < 50; ++j) {
                add_edge(u + i * 50, v + (i + 1) * 50, 1, edge_cost);
                add_edge(v + i * 50, u + (i + 1) * 50, 1, edge_cost);
                edge_cost += 2 * d_val;
            }
        }
    }
    for (int i = 0; i <= 99; ++i) {
        add_edge(0 + i * 50, 5001, numeric_limits<lli>::max(), c_val * i);
    }
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < 99; ++j) {
            add_edge(i + j * 50, i + (j + 1) * 50, numeric_limits<lli>::max(), 0);
        }
    }
    auto result = min_cost_max_flow(5000, 5001);
    assert(result.second == k);
    cout << result.first;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);
    cout << fixed << setprecision(20);
    process();
    return 0;
}
